namespace Trackwise.DbMigrator.Models;

/// <summary>
/// One case from Cold Chain's weekly report on Monday. Seeded by <c>MondayIncidentSeeder</c>;
/// generated by <c>monday-export/scripts/monday_incidents.py</c>.
/// </summary>
public record IncidentData
{
    /// <summary>Monday's number, e.g. <c>CCL-CASENO.078</c>; null for a case Monday never numbered.</summary>
    public string? CaseNumber { get; set; }

    /// <summary>An <c>IncidentKind</c> name.</summary>
    public required string Kind { get; set; }

    /// <summary>An <c>IncidentSeverity</c> name - Monday has none, so it is judged from the text.</summary>
    public string Severity { get; set; } = "Minor";

    public required DateOnly OccurredOn { get; set; }
    public required string Summary { get; set; }
    public string? Prevention { get; set; }

    /// <summary>The TrackWise customer's name.</summary>
    public string? Client { get; set; }

    public string? Plate { get; set; }

    /// <summary>The crew named on the case, drivers and helpers mixed, as Monday lists them.</summary>
    public string[] Crew { get; set; } = [];

    /// <summary><c>Open</c>, <c>UnderReview</c> or <c>Resolved</c>.</summary>
    public string Status { get; set; } = "Open";

    public string? CorrectiveAction { get; set; }

    /// <summary>Who handled it - OPS, CS, the motorpool.</summary>
    public string? AssistedBy { get; set; }

    public decimal? ThirdPartyCompensation { get; set; }
    public string? CrewChargeNote { get; set; }
}

/// <summary>How a tenant's case numbers read, e.g. <c>CCL-CASENO.081</c>.</summary>
public record IncidentSeriesData
{
    public required string Prefix { get; set; }
    public string Separator { get; set; } = "-";
    public int PadWidth { get; set; } = 3;
}
